CREATE TABLE GO_WRITE (ID INTEGER NOT NULL PRIMARY KEY, WRITE_VALUE INTEGER, LABEL VARCHAR(40));
CREATE TABLE GO_DATA (
 ID INTEGER NOT NULL PRIMARY KEY, SMALL_VALUE SMALLINT, INT_VALUE INTEGER,
 FIXED_VALUE CHAR(5), TEXT_VALUE VARCHAR(100), MOMENT TIMESTAMP,
 FIXED_DECIMAL NUMERIC(9,2), WIDE_DECIMAL NUMERIC(12,2),
 FLOAT_VALUE FLOAT, DOUBLE_VALUE DOUBLE PRECISION, ACTIVE_VALUE BOOLEAN,
 TEXT_BLOB BLOB SUB_TYPE 1 CHARACTER SET UTF8, BINARY_BLOB BLOB SUB_TYPE 0);
