CREATE PROCEDURE GO_SUB_TOT_BUDGET (DEPT CHAR(3))
RETURNS (TOT_BUDGET NUMERIC(9,2), AVG_BUDGET NUMERIC(9,2), MIN_BUDGET NUMERIC(9,2), MAX_BUDGET NUMERIC(9,2)) AS
BEGIN
 SELECT SUM(BUDGET), AVG(BUDGET), MIN(BUDGET), MAX(BUDGET) FROM GO_BUDGET
 WHERE HEAD_DEPT = :DEPT INTO :TOT_BUDGET, :AVG_BUDGET, :MIN_BUDGET, :MAX_BUDGET;
 SUSPEND;
END^
SET TERM ; ^
COMMIT;
